  ""effort"": ""auto"",
  ""outputSchema"": {
    ""type"": ""object"",
    ""required"": [
      ""people""
    ],
    ""properties"": {
      ""people"": {
        ""type"": ""array"",
        ""maxItems"": 10,
        ""items"": {
          ""type"": ""object"",
          ""required"": [
            ""name"",
            ""linkedin_url""
          ],
          ""properties"": {
            ""name"": {
              ""type"": ""string""
            },
            ""contact_email"": {
              ""type"": ""string"",
              ""format"": ""email""
            },
            ""linkedin_url"": {
              ""type"": ""string"",
              ""format"": ""uri""
            }
          }
        }
      }
    }
  }
}")!;

var response = await client.Agent.CreateAgentRunAsync(
    request: request
);

